1. 'use strict'
2. const From = require('fastify-reply-from')
3. const WebSocket = require('ws')
4. 
5. const httpMethods = ['DELETE', 'GET', 'HEAD', 'PATCH', 'POST', 'PUT', 'OPTIONS']
6. const urlPattern = /^https?:\/\//
7. 
8. function liftErrorCode (code) {
9.   if (typeof code !== 'number') {
10.     // Sometimes "close" event emits with a non-numeric value
11.     return 1011
12.   } else if (code === 1004 || code === 1005 || code === 1006) {
13.     // ws module forbid those error codes usage, lift to "application level" (4xxx)
14.     return 4000 + (code % 1000)
15.   } else {
16.     return code
17.   }
18. }
19. 
20. function closeWebSocket (socket, code, reason) {
21.   if (socket.readyState === WebSocket.OPEN) {
22.     socket.close(liftErrorCode(code), reason)
23.   }
24. }
25. 
26. function waitConnection (socket, write) {
27.   if (socket.readyState === WebSocket.CONNECTING) {
28.     socket.once('open', write)
29.   } else {
30.     write()
31.   }
32. }
33. 
34. function isExternalUrl (url = '') {
35.   return urlPattern.test(url)
36. };
37. 
38. function proxyWebSockets (source, target) {
39.   function close (code, reason) {
40.     closeWebSocket(source, code, reason)
41.     closeWebSocket(target, code, reason)
42.   }
43. 
44.   source.on('message', data => waitConnection(target, () => target.send(data)))
45.   source.on('ping', data => waitConnection(target, () => target.ping(data)))
46.   source.on('pong', data => waitConnection(target, () => target.pong(data)))
47.   source.on('close', close)
48.   source.on('error', error => close(1011, error.message))
49.   source.on('unexpected-response', () => close(1011, 'unexpected response'))
50. 
51.   // source WebSocket is already connected because it is created by ws server
52.   target.on('message', data => source.send(data))
53.   target.on('ping', data => source.ping(data))
54.   target.on('pong', data => source.pong(data))
55.   target.on('close', close)
56.   target.on('error', error => close(1011, error.message))
57.   target.on('unexpected-response', () => close(1011, 'unexpected response'))
58. }
59. 
60. function setupWebSocketProxy (fastify, options, rewritePrefix) {
61.   const server = new WebSocket.Server({
62.     server: fastify.server,
63.     ...options.wsServerOptions
64.   })
65. 
66.   fastify.addHook('onClose', (instance, done) => server.close(done))
67. 
68.   // To be able to close the HTTP server,
69.   // all WebSocket clients need to be disconnected.
70.   // Fastify is missing a pre-close event, or the ability to
71.   // add a hook before the server.close call. We need to resort
72.   // to monkeypatching for now.
73.   const oldClose = fastify.server.close
74.   fastify.server.close = function (done) {
75.     for (const client of server.clients) {
76.       client.close()
77.     }
78.     oldClose.call(this, done)
79.   }
80. 
81.   server.on('error', (err) => {
82.     fastify.log.error(err)
83.   })
84. 
85.   server.on('connection', (source, request) => {
86.     if (fastify.prefix && !request.url.startsWith(fastify.prefix)) {
87.       fastify.log.debug({ url: request.url }, 'not matching prefix')
88.       source.close()
89.       return
90.     }
91. 
92.     const url = createWebSocketUrl(request)
93. 
94.     const target = new WebSocket(url, options.wsClientOptions)
95. 
96.     fastify.log.debug({ url: url.href }, 'proxy websocket')
97.     proxyWebSockets(source, target)
98.   })
99. 
100.   function createWebSocketUrl (request) {
101.     const source = new URL(request.url, 'http://127.0.0.1')
102. 
103.     const target = new URL(
104.       source.pathname.replace(fastify.prefix, rewritePrefix),
105.       options.upstream
106.     )
107. 
108.     target.search = source.search
109. 
110.     return target
111.   }
112. }
113. 
114. function generateRewritePrefix (prefix, opts) {
115.   if (!prefix) {
116.     return ''
117.   }
118. 
119.   let rewritePrefix = opts.rewritePrefix || new URL(opts.upstream).pathname
120. 
121.   if (!prefix.endsWith('/') && rewritePrefix.endsWith('/')) {
122.     rewritePrefix = rewritePrefix.slice(0, -1)
123.   }
124. 
125.   return rewritePrefix
126. }
127. 
128. async function httpProxy (fastify, opts) {
129.   if (!opts.upstream) {
130.     throw new Error('upstream must be specified')
131.   }
132. 
133.   const preHandler = opts.preHandler || opts.beforeHandler
134.   const rewritePrefix = generateRewritePrefix(fastify.prefix, opts)
135. 
136.   const fromOpts = Object.assign({}, opts)
137.   fromOpts.base = opts.upstream
138.   fromOpts.prefix = undefined
139. 
140.   const oldRewriteHeaders = (opts.replyOptions || {}).rewriteHeaders
141.   const replyOpts = Object.assign({}, opts.replyOptions, {
142.     rewriteHeaders
143.   })
144.   fromOpts.rewriteHeaders = rewriteHeaders
145. 
146.   fastify.register(From, fromOpts)
147. 
148.   if (opts.proxyPayloads !== false) {
149.     fastify.addContentTypeParser('application/json', bodyParser)
150.     fastify.addContentTypeParser('*', bodyParser)
151.   }
152. 
153.   function rewriteHeaders (headers) {
154.     const location = headers.location
155.     if (location && !isExternalUrl(location)) {
156.       headers.location = location.replace(rewritePrefix, fastify.prefix)
157.     }
158.     if (oldRewriteHeaders) {
159.       headers = oldRewriteHeaders(headers)
160.     }
161.     return headers
162.   }
163. 
164.   function bodyParser (req, payload, done) {
165.     done(null, payload)
166.   }
167. 
168.   fastify.route({
169.     url: '/',
170.     method: opts.httpMethods || httpMethods,
171.     preHandler,
172.     config: opts.config || {},
173.     handler
174.   })
175.   fastify.route({
176.     url: '/*',
177.     method: opts.httpMethods || httpMethods,
178.     preHandler,
179.     config: opts.config || {},
180.     handler
181.   })
182. 
183.   function handler (request, reply) {
184.     let dest = request.raw.url
185.     dest = dest.replace(this.prefix, rewritePrefix)
186.     reply.from(dest || '/', replyOpts)
187.   }
188. 
189.   if (opts.websocket) {
190.     setupWebSocketProxy(fastify, opts, rewritePrefix)
191.   }
192. }
193. 
194. httpProxy[Symbol.for('plugin-meta')] = {
195.   fastify: '^3.0.0',
196.   name: 'fastify-http-proxy'
197. }
198. 
199. module.exports = httpProxy
200. module.exports.default = httpProxy
201. module.exports.fastifyHttpProxy = httpProxy
202.

